import OpenAI from 'openai';

const client = new OpenAI({ baseURL: 'https://api.pre.dev/v1', apiKey: process.env.PREDEV_API_KEY });

const completion = await client.chat.completions.create({
  model: 'anthropic/claude-sonnet-5',
  max_tokens: 200,
  messages: [
    { role: 'system', content: 'Answer in one sentence.' },
    { role: 'user', content: 'Why is the sky blue?' },
  ],
});
console.log(completion.choices[0].message.content);

import Anthropic from '@anthropic-ai/sdk';

const client = new Anthropic({ baseURL: 'https://api.pre.dev', apiKey: process.env.PREDEV_API_KEY });

const message = await client.messages.create({
  model: 'anthropic/claude-sonnet-5',
  max_tokens: 256,
  messages: [{ role: 'user', content: 'Give me a haiku about deploys.' }],
});
console.log(message.content);

import OpenAI from 'openai';

const client = new OpenAI({ baseURL: 'https://api.pre.dev/v1', apiKey: process.env.PREDEV_API_KEY });

const result = await client.embeddings.create({
  model: 'openai/text-embedding-3-small',
  input: ['pre.dev builds software from a spec', 'credits pay for model calls'],
});
console.log(result.data[0].embedding.length);

import fs from 'node:fs/promises';
import OpenAI from 'openai';

const client = new OpenAI({ baseURL: 'https://api.pre.dev/v1', apiKey: process.env.PREDEV_API_KEY });

const speech = await client.audio.speech.create({
  model: 'openai/gpt-audio-mini',
  input: 'Your build is ready.',
  voice: 'alloy',
});
await fs.writeFile('ready.wav', Buffer.from(await speech.arrayBuffer()));
